\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Two Ways to Brew Green Tea}
\author{Tea Circle Notes}
\date{2026}

\begin{document}
\maketitle

\section{Hot Brew}
\begin{enumerate}
\item Rinse the pot with hot water.
\item Steep the leaves for 3 minutes at 80 degrees.
\item Pour through a strainer and serve.
\end{enumerate}

\section{Iced Brew}
\begin{enumerate}
\item Rinse the pitcher with cold water.
\item Steep the leaves for three minutes at 80 degrees.
\item Refrigerate the liquor for two hours.
\item Serve over ice with a mint sprig.
\end{enumerate}

\section{Notes}
Use fresh spring water for both methods and pre-chill the glasses
for the iced version.
\end{document}

\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Two Ways to Brew Green Tea}
\author{Tea Circle Notes}
\date{2026}

\begin{document}
\maketitle

\section{Hot Brew}
\begin{enumerate}
\item Rinse the pot with hot water.
\item Steep the leaves for 3 minutes at 80 degrees.
\item Pour through a strainer and serve.
\end{enumerate}

\section{Iced Brew}
\begin{enumerate}
\item Rinse the pitcher with cold water.
\item Steep the leaves for three minutes at 80 degrees.
\item Strain out the leaves.
\item Refrigerate the liquor for two hours.
\item Serve over ice with a mint sprig.
\end{enumerate}

\section{Notes}
Use fresh spring water for both methods and pre-chill the glasses
for the iced version.
\end{document}
